templates.template:
/********************************************
* XenForo.Gen.TR                            *
* Xenistatistik CSS                         *
* eTiKeT 2018                               *
********************************************/

.XenistatikGovde {
	 .xf-xenist_govde()
	 margin-bottom: 10px;

@media (max-width:@xf-responsiveMedium) {
	 .XenistatikBlok {display: initial;}
	 .XenOrtaKolon, .Xenistatistik--altheader { display: none; }
	 }
@media (min-width:@xf-responsiveMedium) {
	 .XenistatikBlok {	display: flex;} 
	.Xenistatistik--altheader { display: table;}
	 }	
@media (max-width:@xf-responsiveMedium) {
	 .XenistatikBlok {display: initial;}
	 .XenOrtaKolon  { display: none; }
	.Xenistatistik--altheader { display: none;}
	 }

	.Xenistatistik--altheader {
		 background-color:  @xf-xenistatistik_alt_header; 
		 color: @xf-xenistatistik_alt_header_metin;
         table-layout: fixed;
         border-collapse: collapse;
         list-style: none;
         margin: 0;
         padding: 0;
         width: 100%;
		 line-height: 10px;

		    .structItem-cell--icon, 
		    .structItem-cell--main,
		    .structItem-cell--meta,
		    .structItem-cell--latest {
			   background-color:  @xf-xenistatistik_alt_header; 
		       color: @xf-xenistatistik_alt_header_metin;	  
               }

			.structItem-cell {
				padding: 5px 2px;
				font-size: 12px;
			    }

		    .Xenistatistik--altheader--sag {
			    text-align: right;
                color: @xf-xenistatistik_alt_header_metin;
		         }
	     }

	.XenistatikBlok {
		 margin: 0 auto;

		.XenKolon {
			flex: 1 1 0;
			overflow: hidden;
			}

       .block-tabHeader {
           background: @xf-xenistatistik_header_renk;
           color: @xf-xenistatistik_header_metin_renk;
           border: none;

        .tabs-tab.is-active {
           background: @xf-xenistatistik_header_aktif_tab_renk;
           color: @xf-xenistatistik_header_aktif_tab_metin_renk;
           border-color: @xf-xenistatistik_header_aktif_tab_sinir_renk;
           }
        }

		.XenSolKolon {
			padding-right: 5px;

			 .structItem-cell.structItem-cell--icon {
	               width: 35px;
                   }

			 .block-tabHeader {
				   border-bottom:none; 
			       }

			 .XenSolAvatarGizle { 
				  .structItem-cell.structItem-cell--icon { display:none;}
			      }

			.Xenistatistik--altheader--text { 
				  color: @xf-xenistatistik_alt_header_metin;
				  text-align: left;
			      }
		  }

		.XenOrtaKolon {
			max-width: 250px;	

			.block {
				 margin-bottom: 5px;
				 }

			.block-row {
            	/* border-top: 1px solid #e7e7e7;*/
                 }

            .contentRow-main { 
              .contentRow-title {
	                  text-overflow: ellipsis;
	                  white-space: nowrap;
	                 overflow: hidden;
                    } 
               }

			.XenistatistikHeader {
			      .xf-xenist_header()

			     a { 
				   color: inherit;
			       }	
            } 		
	     }
	}
 }

.XenistatikGovde { 

	.XenSolKolonGizle {

			.XenOrtaKolon {

			  	    .avatar--xs {
	                     font-size: 15px;
	                     height: 25px;
	                     width: 25px;
                         }		

				    .contentRow--alignMiddle {
	                     height: 22.9px;
                         }

				    .block-row {
	                     padding: 6px 2px;
                         }	  
	        }


			.XenSolKolon {

                .structItem-title {
		            font-size: 14px;
		            height: 25px;
		            overflow: hidden;
		            line-height: 25px;   

					> span { 
						height: 15px;
                        line-height: 15px;
					    }
		         }	

	            .block-body {

			        li { 
					  border-bottom:1px solid rgba(231, 231, 231, 0.1); 
					  }

			        .contentRow-extra--large { 
					     color: rgba(255, 255, 255, 0.5);
				         }
		        }

	            .structItem-cell { 
	                padding: 5px;
	                }

	            .u-dt[title] {
		            float: left;
		            height: 20px;
		            overflow: hidden;
		            text-decoration: none;
		            text-overflow: ellipsis;
                    white-space: nowrap;
		            width: 90px;
		            }

	            .structItem-cell .structItem-cell--icon {
		            width: 35px;
		            }

	            .structItem-iconContainer .avatar {
		            font-size: 15px;
		            height: 25px;
		            width: 25px;
		            }	

	            .structItem-iconContainer .structItem-secondaryIcon {
		            bottom: -5px;
		            font-size: 12px;
		            height: 15px;
		            position: absolute;
		            right: -5px;
		            width: 15px;
		            }

	            .block-footer:not(.block-footer--split) 
				.block-footer-controls {
		            display: none;
		            }

				.XenYeniMesajlar, .XenYeniKonular {

	                  .structItem-minor .structItem-parts, 
	                  .structItem-pageJump,
	                  .structItem-statuses .structItem-status,
	                  .structItem-minor .structItem-extraInfoMinor,
	                  .structItem-cell .structItem-minor dd,
	                  .structItem-cell .structItem-minor dt,
                      .lastPostAv { 
				             display: none; 
				             }
				}

	            .structItem-cell.structItem-cell--meta {
				     width: 100px;
			         }

	            .structItem-cell .structItem-minor {
					  float: right;
                      width: 80px;
                      overflow: hidden;
                      text-overflow: ellipsis;
                      white-space: nowrap;
			          }

	            .structItem-title {
		            font-size: 14px;
		            height: 25px;
		            overflow: hidden;
		            line-height: 25px;    
		            }

	            .pairs.pairs--justified > dt, .structItem-cell {
		            font-size: 12px;
		            }

	            .pairs.pairs--justified > dd { 
		            float: none;
	                text-align: left;
	                }

	            .p-body-sidebar .block-body .block-row  {
		            padding: 5px;
		            }

                .p-body-sidebar .block-body .block-row .avatar.avatar--xs  {
		            font-size: 15px;
		            height: 25px;
		            width: 25px;
		            }

	         @media (max-width:900px) {	
		        .u-dt[title] { display:none;}	
	            }

	         @media (max-width: @xf-responsiveMedium) {
		        .structItem-cell.structItem-cell--meta ,
		        .structItem-cell.structItem-cell--latest:before ,
		        .structItem-cell.structItem-cell--latest a,
		        .structItem-statuses > li, 
		        .structItem-extraInfo > li,
		        .p-body-sidebar .block-container { display:none;}	
	            .XenistatikGovde .structItem-cell { display: inline-block;}			 
               }

	         @media (min-width: @xf-responsiveMedium)  {
	            .structItem-cell  { display: table-cell;  }
                 }

          }
     }
}
